CREATE TABLE IF NOT EXISTS election_chambers (election_id INTEGER NOT NULL REFERENCES elections(id), chamber TEXT NOT NULL CHECK(chamber IN ('congreso','senado')), enabled BOOLEAN NOT NULL DEFAULT FALSE, PRIMARY KEY(election_id,chamber));
CREATE TABLE IF NOT EXISTS election_settings (election_id INTEGER PRIMARY KEY REFERENCES elections(id), date_confirmed BOOLEAN NOT NULL DEFAULT FALSE, conflict_resolver_role TEXT NOT NULL CHECK(conflict_resolver_role='organizacion'));
CREATE TABLE IF NOT EXISTS election_document_types (election_id INTEGER NOT NULL REFERENCES elections(id), chamber TEXT NOT NULL, document_type TEXT NOT NULL, enabled BOOLEAN NOT NULL DEFAULT FALSE, PRIMARY KEY(election_id,chamber,document_type), FOREIGN KEY(election_id,chamber) REFERENCES election_chambers(election_id,chamber));
CREATE TABLE IF NOT EXISTS catalog_imports (id TEXT PRIMARY KEY, election_id INTEGER NOT NULL REFERENCES elections(id), version TEXT NOT NULL, source_name TEXT NOT NULL, source_url TEXT, source_sha256 TEXT NOT NULL, scope TEXT NOT NULL CHECK(scope IN ('national','synthetic')), row_count INTEGER NOT NULL CHECK(row_count > 0), status TEXT NOT NULL CHECK(status IN ('staged','active','superseded')), imported_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, activated_at TIMESTAMP, UNIQUE(election_id,version));
CREATE UNIQUE INDEX IF NOT EXISTS one_active_catalog ON catalog_imports(election_id) WHERE status='active';
CREATE TABLE IF NOT EXISTS catalog_rows (import_id TEXT NOT NULL REFERENCES catalog_imports(id), province_code TEXT NOT NULL, province_name TEXT NOT NULL, municipality_code TEXT NOT NULL, municipality_name TEXT NOT NULL, place_code TEXT NOT NULL, place_name TEXT NOT NULL, district TEXT NOT NULL, section TEXT NOT NULL, table_label TEXT NOT NULL, table_id INTEGER REFERENCES polling_tables(id), PRIMARY KEY(import_id,province_code,municipality_code,district,section,table_label));
CREATE INDEX IF NOT EXISTS catalog_rows_table ON catalog_rows(table_id);
CREATE TABLE IF NOT EXISTS catalog_places (election_id INTEGER NOT NULL REFERENCES elections(id), province_code TEXT NOT NULL, municipality_code TEXT NOT NULL, place_code TEXT NOT NULL, place_id INTEGER NOT NULL REFERENCES polling_places(id), place_name TEXT NOT NULL, PRIMARY KEY(election_id,province_code,municipality_code,place_code));
CREATE TABLE IF NOT EXISTS candidate_votes (document_id TEXT NOT NULL REFERENCES documents(id), candidate_id INTEGER NOT NULL REFERENCES candidates(id), votes INTEGER NOT NULL CHECK(votes >= 0), PRIMARY KEY(document_id,candidate_id));
CREATE TABLE IF NOT EXISTS conflict_resolutions (document_id TEXT PRIMARY KEY REFERENCES documents(id), incumbent_id TEXT NOT NULL REFERENCES documents(id), status TEXT NOT NULL CHECK(status IN ('pending','accepted','kept_incumbent')), resolver_id INTEGER REFERENCES users(id), reason TEXT, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, resolved_at TIMESTAMP);
CREATE INDEX IF NOT EXISTS conflict_resolutions_status ON conflict_resolutions(status);
